SELECT p.id AS position_id, (SELECT MAX(m.price) FROM market_price_event m WHERE m.symbol=p.symbol AND m.observed_at BETWEEN p.opened_at AND p.closed_at) AS hold_high, (SELECT MIN(m.price) FROM market_price_event m WHERE m.symbol=p.symbol AND m.observed_at BETWEEN p.opened_at AND p.closed_at) AS hold_low, (SELECT MAX(m.price) FROM market_price_event m WHERE m.symbol=p.symbol AND m.observed_at BETWEEN p.closed_at AND p.closed_at + INTERVAL 60 MINUTE) AS post60_high, (SELECT MIN(m.price) FROM market_price_event m WHERE m.symbol=p.symbol AND m.observed_at BETWEEN p.closed_at AND p.closed_at + INTERVAL 60 MINUTE) AS post60_low, (SELECT COUNT(*) FROM market_price_event m WHERE m.symbol=p.symbol AND m.observed_at BETWEEN p.opened_at AND p.closed_at) AS hold_events FROM paper_position p WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id